package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.annotation.JsonAnySetter;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.cfg.HandlerInstantiator;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.AnnotatedClass;
import com.fasterxml.jackson.databind.introspect.AnnotatedField;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethod;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospector;
import com.fasterxml.jackson.databind.introspect.POJOPropertiesCollector;
import com.fasterxml.jackson.databind.introspect.POJOPropertyBuilder;
import com.fasterxml.jackson.databind.type.JavaType;
import com.fasterxml.jackson.databind.util.BeanUtil;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class POJOPropertiesCollector__addInjectables_TriageGen1Test {

    private POJOPropertiesCollector collector;
    private MapperConfig<?> mockConfig;
    private JavaType mockType;
    private AnnotatedClass mockClassDef;
    private AnnotationIntrospector mockAi;
    private Map<String, POJOPropertyBuilder> props;

    // Test subclass to access protected method and inject dependencies
    private static class TestablePOJOPropertiesCollector extends POJOPropertiesCollector {
        private final AnnotationIntrospector ai;

        public TestablePOJOPropertiesCollector(MapperConfig<?> config, boolean forSerialization, JavaType type, 
                                              AnnotatedClass classDef, String mutatorPrefix, AnnotationIntrospector ai) {
            super(config, forSerialization, type, classDef, mutatorPrefix);
            this.ai = ai;
            // Use reflection to set the private/protected _annotationIntrospector field if necessary, 
            // but since we are testing the logic, we can mock the behavior via the constructor or reflection.
            try {
                java.lang.reflect.Field field = POJOPropertiesCollector.class.getDeclaredField("_annotationIntrospector");
                field.setAccessible(true);
                field.set(this, ai);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }

        @Override
        public void _doAddInjectable(Object id, AnnotatedMember m) {
            // Mocking the behavior of _doAddInjectable to verify if it's called correctly
            super._doAddInjectable(id, m);
        }

        // Override to allow spying on the actual method call without needing a real internal state
        public void callAddInjectables(Map<String, POJOPropertyBuilder> p) {
            this._addInjectables(p);
        }
    }

    @Before
    public void setUp() {
        mockConfig = mock(MapperConfig.class);
        mockType = mock(JavaType.class);
        mockClassDef = mock(AnnotatedClass.class);
        mockAi = mock(AnnotationIntrospector.class);
        props = new HashMap<>();
    }

    @Test
    public void testAddInjectables_NullAi() throws Exception {
        // Arrange: ai is null
        TestablePOJOPropertiesCollector collectorWithNullAi = new TestablePOJOPropertiesCollector(
                mockConfig, true, mockType, mockClassDef, "", null);

        // Act & Assert: Should return immediately without error
        collectorWithNullAi.callAddInjectables(props);
        verifyNoInteractions(mockClassDef);
    }

    @Test
    public void testAddInjectables_WithFieldsAndMethods() throws Exception {
        // Arrange
        TestablePOJOPropertiesCollector spyCollector = spy(new TestablePOJOPropertiesCollector(
                mockConfig, true, mockType, mockClassDef, "", mockAi));

        // Mock Fields
        AnnotatedField field1 = mock(AnnotatedField.class);
        AnnotatedField field2 = mock(AnnotatedField.class);

        // Mock Methods
        AnnotatedMethod method1 = mock(AnnotatedMethod.class); // 1 param -> valid
        AnnotatedMethod method2 = mock(AnnotatedMethod.class); // 2 params -> skip
        AnnotatedMethod method3 = mock(AnnotatedMethod.class); // 0 params -> skip

        // Setup ClassDef iterators
        // Fields
        Iterator<AnnotatedField> fieldIterator = java.util.Arrays.asList(field1, field2).iterator();
        when(mockClassDef.fields()).thenAnswer(inv -> fieldIterator);

        // Methods
        Iterator<AnnotatedMethod> methodIterator = java.util.Arrays.asList(method1, method2, method3).iterator();
        when(mockClassDef.memberMethods()).thenAnswer(inv -> methodIterator);

        // Setup Params
        when(method1.getParameterCount()).thenReturn(1);
        when(method2.getParameterCount()).thenReturn(2);
        when(method3.getParameterCount()).thenReturn(0);

        // Setup AI return values
        Object fieldId = "fieldId";
        Object methodId = "methodId";
        when(mockAi.findInjectableValueId(field1)).thenReturn(fieldId);
        when(mockAi.findInjectableValueId(field2)).thenReturn(fieldId);
        when(mockAi.findInjectableValueId(method1)).thenReturn(methodId);
        // method2 and method3 should be skipped before AI call

        // Act
        spyCollector.callAddInjectables(props);

        // Assert
        // Verify _doAddInjectable was called for field1, field2, and method1
        verify(spyCollector)._doAddInjectable(eq(fieldId), eq(field1));
        verify(spyCollector)._doAddInjectable(eq(fieldId), eq(field2));
        verify(spyCollector)._doAddInjectable(eq(methodId), eq(method1));

        // Verify method2 and method3 were not processed via AI
        verify(mockAi, never()).findInjectableValueId(method2);
        verify(mockAi, never()).findInjectableValueId(method3);
    }

    @Test
    public void testAddInjectables_NoFieldsNoMethods() throws Exception {
        // Arrange
        TestablePOJOPropertiesCollector collector = new TestablePOJOPropertiesCollector(
                mockConfig, true, mockType, mockClassDef, "", mockAi);

        when(mockClassDef.fields()).thenReturn(Collections.emptyList());
        when(mockClassDef.memberMethods()).thenReturn(Collections.emptyList());

        // Act
        collector.callAddInjectables(props);

        // Assert
        verify(mockAi, never()).findInjectableValueId(any());
    }
}
